// Sound effects with plain Web Audio: positional (volume falls off with distance from the
// camera, left/right pan), a little pitch variation so repeats don't sound robotic, and a
// cap on overlapping copies per sound so rapid fire stays clean. Files are generated by
// `pnpm sfx` into public/sfx (see tools/sfx.json).
import type { Vec2 } from '@stuffed/sim';

export const SOUNDS = [
  'cork_pop', 'dart_shot', 'soaker_shot', 'hit_stuffing', 'hit_armor', 'impact', 'splash', 'knockout',
  'chest_rattle', 'chest_open', 'pickup_weapon', 'pickup_item', 'heal', 'armor_up', 'reload', 'swap',
  'jump', 'land', 'rinse_rising', 'soggy', 'win', 'lose', 'click',
  'band_twang', 'band_stretch', 'marble_shot', 'marble_bounce', 'marble_burst', 'pillow_swing', 'pillow_bonk',
  'glitter_throw', 'glitter_burst', 'bubble_blow', 'bubble_pop', 'juice_slurp', 'ball_boing', 'cardboard_place', 'bag_rustle',
] as const;
export type SoundName = (typeof SOUNDS)[number];

/** Beyond this distance (world units) from the listener a sound is silent. */
const HEARING = 28;
/** Distance at which a sound is panned fully to one side. */
const PAN_WIDTH = 16;
const MAX_VOICES = 5;
const MUTE_KEY = 'stuffed.muted';
const NOTHING = () => {};

export interface PlayOptions {
  /** World position; omitted = non-positional (UI, announcements). */
  at?: Vec2;
  volume?: number;
  /** Random pitch spread, e.g. 0.1 = ±5%. */
  pitchSpread?: number;
}

export class Sound {
  /** Where the camera is; positional sounds are heard from here. */
  readonly listener: Vec2 = { x: 0, y: 0 };
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private readonly buffers = new Map<SoundName, AudioBuffer>();
  private readonly voices = new Map<SoundName, number>();
  private muted = false;

  constructor(private readonly baseUrl: string) {
    try {
      this.muted = localStorage.getItem(MUTE_KEY) === '1';
    } catch {
      // storage blocked: start unmuted
    }
    // Browsers only allow audio after a user gesture.
    const unlock = () => {
      this.start();
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
    };
    window.addEventListener('pointerdown', unlock);
    window.addEventListener('keydown', unlock);
  }

  get isMuted(): boolean {
    return this.muted;
  }

  toggleMute(): boolean {
    this.muted = !this.muted;
    if (this.master) this.master.gain.value = this.muted ? 0 : 1;
    try {
      localStorage.setItem(MUTE_KEY, this.muted ? '1' : '0');
    } catch {
      // not persisted; fine
    }
    return this.muted;
  }

  /** Plays a sound; the returned function fades it out early (a no-op once it has ended). */
  play(name: SoundName, { at, volume = 1, pitchSpread = 0.1 }: PlayOptions = {}): () => void {
    const ctx = this.ctx;
    const buffer = this.buffers.get(name);
    if (!ctx || !this.master || !buffer || this.muted) return NOTHING;

    let gain = volume;
    let pan = 0;
    if (at) {
      const dx = at.x - this.listener.x;
      const dy = at.y - this.listener.y;
      const d = Math.hypot(dx, dy);
      if (d >= HEARING) return NOTHING;
      gain *= (1 - d / HEARING) ** 1.6;
      pan = Math.max(-1, Math.min(1, dx / PAN_WIDTH));
    }
    if (gain < 0.02) return NOTHING;
    const playing = this.voices.get(name) ?? 0;
    if (playing >= MAX_VOICES) return NOTHING;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.playbackRate.value = 1 + (Math.random() - 0.5) * pitchSpread;
    const g = ctx.createGain();
    g.gain.value = gain;
    const p = ctx.createStereoPanner();
    p.pan.value = pan;
    source.connect(g).connect(p).connect(this.master);
    this.voices.set(name, playing + 1);
    let ended = false;
    source.onended = () => {
      ended = true;
      this.voices.set(name, Math.max(0, (this.voices.get(name) ?? 1) - 1));
    };
    source.start();
    return () => {
      if (ended) return;
      const now = ctx.currentTime;
      g.gain.setValueAtTime(g.gain.value, now);
      g.gain.linearRampToValueAtTime(0, now + 0.08);
      source.stop(now + 0.1);
    };
  }

  private start(): void {
    if (this.ctx) return;
    this.ctx = new AudioContext();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 1;
    this.master.connect(this.ctx.destination);
    void this.ctx.resume();
    for (const name of SOUNDS) void this.load(name);
  }

  private async load(name: SoundName): Promise<void> {
    try {
      const res = await fetch(`${this.baseUrl}sfx/${name}.mp3`);
      if (!res.ok) return;
      this.buffers.set(name, await this.ctx!.decodeAudioData(await res.arrayBuffer()));
    } catch {
      // a missing or broken file just stays silent
    }
  }
}
